#!/usr/bin/env python3
"""Build a dependency-free HTML guide from case content and real captures."""
from __future__ import annotations
import argparse, base64, hashlib, html, json, re, zipfile
from pathlib import Path

ROOT=Path(__file__).resolve().parents[2]
HERE=Path(__file__).resolve().parent
E=html.escape
STYLE='''
:root{--ink:#173047;--muted:#526578;--line:#d9e1e8;--paper:#f3f6f9;--accent:#176b72;--amber:#9b5a14}*{box-sizing:border-box}html{scroll-behavior:smooth;scroll-padding-top:75px}body{margin:0;background:var(--paper);color:var(--ink);font:16px/1.62 system-ui,-apple-system,Segoe UI,sans-serif}a{color:#075d80;text-underline-offset:3px}header{background:#142c42;color:white;padding:48px max(24px,calc((100vw - 1180px)/2)) 38px}header p{max-width:950px;color:#dce8f0}h1{font-size:clamp(28px,4vw,46px);line-height:1.14;margin:10px 0 18px;letter-spacing:-1px}h2{font-size:25px;margin:0 0 14px}h3{font-size:18px;margin:0 0 10px}.eyebrow{font:700 12px/1.3 system-ui;letter-spacing:2px;text-transform:uppercase;color:#a8d9dc}.stats{display:flex;flex-wrap:wrap;gap:26px;margin-top:24px}.stats strong{display:block;font-size:26px}.stats span{font-size:13px;color:#dce8f0}.wrap{max-width:1230px;margin:auto;padding:26px 24px 70px}.notice{background:#fff8e9;border-left:4px solid #bd842c;padding:15px 20px;margin-bottom:28px}.route{background:white;border:1px solid var(--line);padding:24px;border-radius:10px}.route-grid{display:grid;grid-template-columns:1fr 1.6fr;gap:20px}.route-box{padding:16px;background:#f2f7f8;border:1px solid #d5e5e6}.route-box p{margin:8px 0}.formula{font-family:ui-monospace,SFMono-Regular,Consolas,monospace;background:#edf3f6;padding:10px 12px;font-size:14px;overflow-wrap:anywhere}.toolbar{position:sticky;top:0;z-index:5;background:#f3f6f9f5;backdrop-filter:blur(8px);padding:14px 0;border-bottom:1px solid var(--line);margin:20px 0;display:flex;gap:10px;flex-wrap:wrap;align-items:center}input[type=search]{min-width:200px;flex:1;font:inherit;padding:9px 12px;border:1px solid #bac9d4;border-radius:6px}select,button{font:600 14px system-ui;padding:10px 13px;background:white;color:var(--ink);border:1px solid #bac9d4;border-radius:5px;cursor:pointer}button:hover{background:#e9f2f4}button:focus-visible,a:focus-visible,summary:focus-visible{outline:3px solid #00a9ad;outline-offset:3px}.count{font-size:13px;color:var(--muted)}.section-title{display:flex;align-items:center;gap:12px;margin:30px 0 12px}.section-title:after{content:'';flex:1;height:1px;background:var(--line)}details.case{border:1px solid var(--line);background:white;border-radius:8px;margin:10px 0;overflow:hidden}details.case summary{cursor:pointer;padding:17px 19px;list-style:none;display:flex;gap:12px;align-items:baseline}details.case summary::-webkit-details-marker{display:none}details.case summary:before{content:'+';font-size:19px;color:var(--accent);font-weight:bold}details.case[open] summary:before{content:'−'}details.case[open] summary{border-bottom:1px solid var(--line);background:#f8fbfc}summary strong{font-size:18px}.badge{font-size:11px;letter-spacing:.7px;text-transform:uppercase;border:1px solid #cbd9df;padding:2px 7px;border-radius:4px;white-space:nowrap}.case-body{display:grid;grid-template-columns:minmax(280px,.93fr) minmax(320px,1.1fr);gap:24px;padding:22px}.case-body figure{margin:0;align-self:start}.case-body img{width:100%;height:auto;display:block;border:1px solid var(--line);border-radius:4px;aspect-ratio:640/770;background:white}.controls{display:flex;flex-wrap:wrap;gap:8px;align-items:center;margin:10px 0}.controls a{font-size:13px}.caption{font-size:12px;color:var(--muted)}.notes h4{font-size:11px;text-transform:uppercase;letter-spacing:1px;color:var(--accent);margin:16px 0 5px}.notes h4:first-child{margin-top:0}.notes p{margin:0 0 10px}.scope{padding:12px 14px;background:#fff8e9;border-left:3px solid #bd842c;font-size:14px}.source{font-size:12px;border-top:1px solid var(--line);padding-top:12px;overflow-wrap:anywhere}.related{font-size:13px}.replay{margin-top:30px;padding:22px;background:white;border:1px solid var(--line);border-radius:8px}.replay pre{padding:14px;background:#edf3f6;overflow:auto;font-size:13px}.replay code{overflow-wrap:anywhere}.fine{font-size:13px;color:var(--muted)}[hidden]{display:none!important}footer{padding:30px 0;border-top:1px solid var(--line);font-size:13px;color:var(--muted)}@media(max-width:800px){.route-grid,.case-body{grid-template-columns:1fr}.wrap{padding:18px 14px 40px}header{padding:30px 20px}.case-body{padding:15px}.case-body figure{max-width:570px;width:100%;margin:auto}.toolbar{gap:7px}summary strong{font-size:16px}.badge{display:none}}@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}}@media print{.toolbar,.controls{display:none}.case-body{display:block}.case-body img{max-width:400px}details.case{break-inside:avoid}header{background:white;color:black}.stats{display:none}}
'''
SCRIPT='''
const cases=[...document.querySelectorAll('details.case')];
function stopAll(){document.querySelectorAll('button.play[aria-pressed="true"]').forEach(b=>{const i=document.getElementById(b.dataset.image);i.src=i.dataset.poster;b.textContent='Play GIF';b.setAttribute('aria-pressed','false')})}
document.querySelectorAll('button.play').forEach(b=>b.addEventListener('click',()=>{const was=b.getAttribute('aria-pressed')==='true';stopAll();if(!was){const i=document.getElementById(b.dataset.image);i.src=i.dataset.gif;b.textContent='Pause animation';b.setAttribute('aria-pressed','true')}}));
document.getElementById('pause').addEventListener('click',stopAll);
function filter(){stopAll();const q=document.getElementById('search').value.toLowerCase(),g=document.getElementById('group').value;let n=0;cases.forEach(c=>{const ok=(!g||c.dataset.group===g)&&c.textContent.toLowerCase().includes(q);c.hidden=!ok;if(ok){n++;if(q)c.open=true}});document.querySelectorAll('.case-group').forEach(g=>g.hidden=![...g.querySelectorAll('.case')].some(c=>!c.hidden));document.getElementById('count').textContent=n+' / '+cases.length+' entries'}
document.getElementById('search').addEventListener('input',filter);document.getElementById('group').addEventListener('change',filter);
function reveal(){const id=decodeURIComponent(location.hash.slice(1)),el=document.getElementById(id);if(el&&el.matches('details.case')){document.getElementById('search').value='';document.getElementById('group').value='';filter();el.open=true;el.scrollIntoView()}}
window.addEventListener('hashchange',reveal);reveal();filter();
document.querySelectorAll('details.case').forEach(c=>c.addEventListener('toggle',()=>{if(!c.open){const b=c.querySelector('button.play');if(b&&b.getAttribute('aria-pressed')==='true')b.click()}}));
'''

def build(folder=HERE, standalone=None):
    data=json.loads((folder/'cases.json').read_text());capture=json.loads((folder/'capture.json').read_text());scenes={s['id']:s for s in capture['scenes']}
    proof=data['proofRevision'];visual=data['visualizerRevision'];base=f'https://github.com/dylan0301/hexagon-cover-database/blob/{proof}/'
    labels={}
    for p in sorted((ROOT/'arrange/paper_draft').rglob('*.tex')):
        if {'inline_proofs','alternatives'} & set(p.parts):continue
        for label in re.findall(r'\\label\{([^}]+)\}',p.read_text()):labels.setdefault(label,str(p.relative_to(ROOT)))
    byid={c['id']:c for c in data['cards']};parts=[]
    for group in data['groups']:
        parts.append(f'<section class="case-group"><h2 class="section-title">{E(group)}</h2>')
        for c in [c for c in data['cards'] if c['group']==group]:
            s=scenes[c['scene']];id=c['id'];scene=c['scene'];kind=s['snapshotKind'];
            src=(f'https://github.com/jcpaik/hexagon-cover-visual/blob/{visual}/'+c['source'][11:]) if c['source'].startswith('VISUALIZER:') else base+c['source']
            links=' · '.join(f'<a href="{base+labels[label]}">{E(label)}</a>' for label in c['labels'])
            related=' · '.join(f'<a href="#{r}">{E(byid[r]["title"] if r in byid else "Proof route")}</a>' for r in c['related'])
            zoom=' Uniform 0.72× capture zoom keeps the full local triangles visible.' if s.get('captureZoom')==.72 else ''
            overlay=' Magenta supporting line is an added annotation.' if scene.startswith('f-contact-') else ' Magenta marks the measured supplier interval.' if scene.startswith('supplier-') else ''
            parts.append(f'''<details class="case" id="{id}" data-group="{E(group)}"{' open' if id=='bc-one' else ''}><summary><span class="badge">{E(group)}</span><strong>{E(c['title'])}</strong></summary><div class="case-body"><figure>
<img id="image-{id}" loading="lazy" src="assets/{scene}.png" data-poster="assets/{scene}.png" data-gif="assets/{scene}.gif" alt="{E(c['title'])}. {E(c['construction'])}">
<div class="controls"><button class="play" type="button" aria-pressed="false" data-image="image-{id}">Play GIF</button><a href="assets/{scene}.gif" download>GIF</a><a href="snapshots/{scene}.json" download>{kind.title()} JSON</a></div>
<figcaption class="caption">{s['frameCount']} captured states · {s['durationMs']/1000:.1f} s loop · {E(s['mode'])}.{zoom}{overlay} Start/stop is manual; only one GIF plays at a time.</figcaption></figure><div class="notes"><h4>Hypotheses</h4><p>{E(c['hypothesis'])}</p><h4>What to watch</h4><p>{E(c['construction'])}</p><h4>Why this closes the branch</h4><p>{E(c['argument'])}</p><p class="scope"><strong>Scope.</strong> {E(c['scope'])}</p><p class="source"><a href="{src}">Pinned source</a>{' · '+links if links else ''}</p><p class="related">Continue: {related}</p></div></div></details>''')
        parts.append('</section>')
    html_text=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="description" content="Animated guide to the hexagon-cover proof, with reproducible captures from the live visualizer."><title>Hexagon Cover — Animated Proof Guide</title><style>{STYLE}</style></head><body>
<header><div class="eyebrow">Hexagon-cover proof / visual companion</div><h1>From boundary gaps<br>to fixed witnesses</h1><p>Read the case route first. Then open an entry, play its animation, and follow the pinned proof source. Every geometry clip is captured from the Hexagon Cover visualizer; examples and explanatory annotations are recorded separately from proof claims.</p><div class="stats"><div><strong>{len(scenes)}</strong><span>distinct animated GIFs</span></div><div><strong>{len(data['cards'])}</strong><span>case / subcase / tool entries</span></div><div><strong>3</strong><span>fixed witness families: BC, D, F</span></div><div><strong>{sum(s['frameCount'] for s in scenes.values())}</strong><span>validated rendered states</span></div></div></header>
<main class="wrap"><div class="notice"><strong>How to read these examples.</strong> A terminal proof branch assumes a cover and derives a contradiction; no example can realize all those hypotheses simultaneously. Local triangles, a boundary-only cover, and witness constructions are therefore labeled separately. Uppercase A, B, C are actual maximal reaches; lowercase a, b, c are selected demands. N+ always counts actual A+B&gt;1. Open U triangles and closed T triangles must not be confused.</div>
<section class="route" id="route"><h2>The complete terminal route</h2><p>First prove <a href="#n0-gap">N+ ≥ 1</a>. For a hypothetical cover, use actual boundary gaps—including singletons.</p><div class="route-grid"><div class="route-box"><h3>No gaps</h3><p><strong>N+ = 1</strong> → <a href="#f-frontier">F: nine points</a>.</p><p><strong>N+ ≥ 2</strong> → <a href="#area-cyclic">cyclic area loss</a>.</p><p>F splits into <a href="#f-disk">disk-only range</a> and <a href="#f-newton">Newton / four-contact range</a>.</p></div><div class="route-box"><h3>At least one gap</h3><p><a href="#skeleton-budget">Length budgets</a> reduce to N+=1, Nsp≤1. Let M_k be the C midpoint and sigma the unique supercritical index.</p><p><strong>sigma = k</strong> → <a href="#bc-one">BC</a> (one or two gaps).</p><p><strong>sigma ≠ k</strong> → a unique adjacent midpoint supplier: T3-like → <a href="#d-t3-one">D</a>; Vd2 → <a href="#vd2-budget">perimeter</a>; Vd1 at k → <a href="#d-vd1-one">D</a>; Vd1 away from k → <a href="#replacement-minus">two-chart replacement</a> → N0.</p></div></div><p class="fine">The normalized positive-support classification, candidate CE1/CE2 split, both gap layouts, singleton endpoints, both replacement charts, both area orientation sectors, and all four hard-range contacts have dedicated entries. Ordinary V types are not redundantly split inside BC or F.</p></section>
<div class="toolbar"><input id="search" type="search" aria-label="Search cases and explanations" placeholder="Search: singleton, T3, Newton, tangent…"><select id="group" aria-label="Filter chapter"><option value="">All chapters</option>{''.join(f'<option>{E(g)}</option>' for g in data['groups'])}</select><button id="pause" type="button">Pause animation</button><span id="count" class="count" aria-live="polite"></span></div>
{''.join(parts)}
<section class="replay" id="reproduce"><h2>Reproduce an example</h2><p>Open <a href="https://hexagon-cover-visual.surge.sh/">the visualizer</a>. For a <strong>Controller JSON</strong>, paste the downloaded JSON into <em>Controller State</em> and load it. For a <strong>Free JSON</strong>, first select <em>Free</em>, then paste into <em>Free State</em> and load. Source-view settings and magenta overlays are capture instructions, not fields in the saved JSON.</p><p>The files in this folder work offline: open <code>index.html</code> next to <code>assets/</code> and <code>snapshots/</code>. GitHub’s file viewer displays HTML source; it does not deploy this page. See <a href="README.md">reproduction instructions</a>, <a href="capture.json">per-frame measurements and provenance</a>, and <a href="cases.json">case mapping</a>.</p><p class="fine">Proof revision: <code>{proof}</code><br>Visualizer source revision: <code>{visual}</code><br>Capture mode: <code>{E(capture['provenance']['captureMode'])}</code>. Browser and deployed JavaScript hashes are recorded in capture.json. Four-contact support tests and area clipping are numerical checks, not new exact certificates.</p></section>
<footer>The canonical paper and numbered proof sources retain authority. No proof statement, formal case routing, or publication PDF was changed by this guide. Captures use the existing app’s rendering; uniform local-view zoom, caption strips, and explicitly marked contact/interval annotations are presentation-only. <a href="#route">Back to the proof route</a></footer></main><script>{SCRIPT}</script></body></html>'''
    (folder/'index.html').write_text(html_text)
    if standalone:
        def datauri(path):
            p=folder/path;suffix=p.suffix;mime={'.gif':'image/gif','.png':'image/png','.json':'application/json','.md':'text/plain'}[suffix]
            return f'data:{mime};base64,'+base64.b64encode(p.read_bytes()).decode()
        standalone_text=re.sub(r'(?P<attr>src|data-poster|data-gif|href)="(?P<path>(?:assets/[^" ]+\.(?:gif|png)|snapshots/[^" ]+\.json|README\.md|capture\.json|cases\.json))"',lambda m:f'{m["attr"]}="{datauri(m["path"])}"',html_text)
        standalone.parent.mkdir(parents=True,exist_ok=True);standalone.write_text(standalone_text)
    print(f'Built {len(data["cards"])} entries from {len(scenes)} captured animations.')

if __name__=='__main__':
    ap=argparse.ArgumentParser();ap.add_argument('--folder',type=Path,default=HERE);ap.add_argument('--standalone',type=Path);args=ap.parse_args();build(args.folder,args.standalone)
